insert into public.age_groups(id,name,min_age,max_age) values('d2000000-0000-4000-8000-000000000005','Development ages',5,10);
insert into public.academy_classes(id,branch_id,venue_id,coach_id,sport,level_id,age_group_id,name,capacity,weekdays,local_time,duration_minutes) values('d2000000-0000-4000-8000-000000000006','d2000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000002','d1000000-0000-4000-8000-000000000002','swimming','d2000000-0000-4000-8000-000000000003','d2000000-0000-4000-8000-000000000005','Development session',10,array[0],'17:00',60);
insert into public.class_sessions(id,class_id,starts_at,ends_at,capacity) values('d2000000-0000-4000-8000-000000000007','d2000000-0000-4000-8000-000000000006',now()-interval '2 hours',now()-interval '1 hour',10);
insert into public.families(id,name) values('d3000000-0000-4000-8000-000000000001','Development family');
insert into public.guardians values('d3000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000001');
insert into public.children(id,family_id,name,reported_age,age_captured_on) values('d3000000-0000-4000-8000-000000000002','d3000000-0000-4000-8000-000000000001','Synthetic Athlete',7,current_date);
insert into public.child_sports(child_id,sport,level_id,level,status) values('d3000000-0000-4000-8000-000000000002','swimming','d2000000-0000-4000-8000-000000000003','Development beginner','reviewed');
insert into public.enrollments(id,child_id,class_id) values('d3000000-0000-4000-8000-000000000003','d3000000-0000-4000-8000-000000000002','d2000000-0000-4000-8000-000000000006');
insert into public.session_roster(session_id,enrollment_id,kind,attendance) values('d2000000-0000-4000-8000-000000000007','d3000000-0000-4000-8000-000000000003','enrollment','present');
create function pg_temp.dev_cmd(a text,d jsonb) returns jsonb language sql as $$select public.product_command(a,d,gen_random_uuid())$$;
grant execute on function pg_temp.dev_cmd(text,jsonb) to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select pg_temp.dev_cmd('development.criteria.create','{"sport":"swimming","level_id":"d2000000-0000-4000-8000-000000000003","title":"Development skills","criteria":[{"key":"distance","label":"Distance","unit":"m","min":0,"max":100,"direction":"higher"}]}')$$,'Reviewer configures versioned sport criteria');
select lives_ok($$select pg_temp.dev_cmd('development.criteria.create','{"sport":"swimming","level_id":"d2000000-0000-4000-8000-000000000003","title":"Development skills revision","criteria":[{"key":"distance","label":"Distance","unit":"m","min":0,"max":200,"direction":"higher"}]}')$$,'Criteria revision creates another version');
select is((select max(version) from public.development_criteria where level_id='d2000000-0000-4000-8000-000000000003'),2,'Version history retained');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is(jsonb_array_length(public.development_sessions()),1,'Assigned coach sees session projection');
select ok(not (public.development_sessions()::text like '%family_id%'),'Coach projection omits family identifiers and contact');
select throws_ok($$select pg_temp.dev_cmd('development.criteria.create','{"sport":"swimming","level_id":"d2000000-0000-4000-8000-000000000003","title":"Unauthorized","criteria":[]}')$$,'42501',null,'Coach cannot configure standards');
select throws_ok($$select pg_temp.dev_cmd('development.assessment.save',jsonb_build_object('session_id','d2000000-0000-4000-8000-000000000007','child_id','d3000000-0000-4000-8000-000000000002','criteria_id',(select id from public.development_criteria where level_id='d2000000-0000-4000-8000-000000000003' and version=1),'scores','{"distance":101}'::jsonb,'summary','Too far'))$$,'22023',null,'Assessment range validated against exact version');
select throws_ok($$select pg_temp.dev_cmd('development.assessment.save',jsonb_build_object('next_target',repeat('x',1001)))$$,'22023',null,'SQL enforces bounded next training target before authoring');
select lives_ok($$select pg_temp.dev_cmd('development.assessment.save',jsonb_build_object('session_id','d2000000-0000-4000-8000-000000000007','child_id','d3000000-0000-4000-8000-000000000002','criteria_id',(select id from public.development_criteria where level_id='d2000000-0000-4000-8000-000000000003' and version=1),'scores','{"distance":25}'::jsonb,'summary','Improved confidence','next_target','Practice the reviewed 25 metre technique.','internal_note','Private coaching note','recommended_level_id','d2000000-0000-4000-8000-000000000004'))$$,'Assigned coach saves draft');
select set_config('test.assessment',(select id::text from public.development_assessments where child_id='d3000000-0000-4000-8000-000000000002'),true);
select is((select count(*)::int from public.development_assessment_notes where assessment_id=current_setting('test.assessment')::uuid),1,'Coach can read private notes');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_assessments where child_id='d3000000-0000-4000-8000-000000000002'),0,'Parent cannot see draft');
select is((select count(*)::int from public.development_assessment_notes),0,'Parent cannot see private notes');
select throws_ok($$select pg_temp.dev_cmd('development.assessment.submit',jsonb_build_object('id',current_setting('test.assessment')))$$,'42501',null,'Parent cannot submit draft');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select pg_temp.dev_cmd('development.assessment.submit',jsonb_build_object('id',current_setting('test.assessment')))$$,'Coach submits completed evidence');
select throws_ok($$select pg_temp.dev_cmd('development.assessment.review',jsonb_build_object('id',current_setting('test.assessment'),'decision','approved','reason','Reviewed evidence'))$$,'42501',null,'Coach cannot approve own assessment');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select pg_temp.dev_cmd('development.assessment.publish',jsonb_build_object('id',current_setting('test.assessment')))$$,'P0409',null,'Submission cannot bypass review');
select lives_ok($$select pg_temp.dev_cmd('development.assessment.review',jsonb_build_object('id',current_setting('test.assessment'),'decision','approved','reason','Evidence checked'))$$,'Independent reviewer approves');
select lives_ok($$select pg_temp.dev_cmd('development.assessment.publish',jsonb_build_object('id',current_setting('test.assessment')))$$,'Reviewer publishes');
select lives_ok($$select pg_temp.dev_cmd('development.level.approve',jsonb_build_object('assessment_id',current_setting('test.assessment'),'reason','Ready for next level'))$$,'Published recommendation can be approved');
select lives_ok($$select pg_temp.dev_cmd('development.certificate.issue',jsonb_build_object('assessment_id',current_setting('test.assessment'),'title','Confidence award'))$$,'Certificate issued from published evidence');
select set_config('test.certificate',(select id::text from public.development_certificates where assessment_id=current_setting('test.assessment')::uuid),true);
select is((select level_id::text from public.child_sports where child_id='d3000000-0000-4000-8000-000000000002'),'d2000000-0000-4000-8000-000000000004','Approved level updates only sport profile');
select is((select class_id::text from public.enrollments where id='d3000000-0000-4000-8000-000000000003'),'d2000000-0000-4000-8000-000000000006','Progression never silently moves class');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_assessments where child_id='d3000000-0000-4000-8000-000000000002'),1,'Parent sees published assessment');
select is((select count(*)::int from public.development_assessment_notes),0,'Published assessment still hides internal notes');
select is((select next_target from public.development_assessments where id=current_setting('test.assessment')::uuid),'Practice the reviewed 25 metre technique.','Next training target becomes visible only with reviewed published evidence');
select is((select value::int from public.development_results where assessment_id=current_setting('test.assessment')::uuid),25,'Published metric retains true measured value');
select is((select count(*)::int from public.development_level_history where child_id='d3000000-0000-4000-8000-000000000002'),1,'Parent sees independent sport history');
select is((select count(*)::int from public.development_certificates where id=current_setting('test.certificate')::uuid),1,'Certificate visible to own family');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_certificates where id=current_setting('test.certificate')::uuid),0,'Unrelated family cannot download certificate');
select is(jsonb_array_length(public.development_sessions()),0,'Unassigned user gets no coach roster');
select throws_ok($$select pg_temp.dev_cmd('development.plan.save','{"session_id":"d2000000-0000-4000-8000-000000000007","objectives":"Unauthorized coach","activities":"No access"}')$$,'42501',null,'Unassigned account cannot author a plan');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select pg_temp.dev_cmd('development.plan.save','{"session_id":"d2000000-0000-4000-8000-000000000007","objectives":"Build confidence","activities":"Supervised drills","internal_note":"Private session note"}')$$,'Assigned coach saves private session plan');
select throws_ok($$select pg_temp.dev_cmd('development.report.create',jsonb_build_object('session_id','d2000000-0000-4000-8000-000000000007','child_id','d3000000-0000-4000-8000-000000000002','month',to_char(now() at time zone 'Asia/Dubai','YYYY-MM'),'summary','Invented evidence','evidence_ids',jsonb_build_array('d9000000-0000-4000-8000-000000000001')))$$,'22023',null,'Report rejects invented evidence');
select lives_ok($$select pg_temp.dev_cmd('development.report.create',jsonb_build_object('session_id','d2000000-0000-4000-8000-000000000007','child_id','d3000000-0000-4000-8000-000000000002','month',to_char((now()-interval '2 hours') at time zone 'Asia/Dubai','YYYY-MM'),'summary','Monthly progress grounded in assessment','evidence_ids',jsonb_build_array(current_setting('test.assessment'))))$$,'Coach creates report with same-month published evidence');
select set_config('test.report',(select id::text from public.development_reports where child_id='d3000000-0000-4000-8000-000000000002'),true);
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_reports where child_id='d3000000-0000-4000-8000-000000000002'),0,'Report drafts hidden from parent');
select is((select count(*)::int from public.development_session_plans where session_id='d2000000-0000-4000-8000-000000000007'),0,'Internal session plans hidden from parent');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select pg_temp.dev_cmd('development.report.submit',jsonb_build_object('id',current_setting('test.report')))$$,'Coach submits report');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select pg_temp.dev_cmd('development.report.publish',jsonb_build_object('id',current_setting('test.report')))$$,'P0409',null,'Report publication cannot bypass review');
select lives_ok($$select pg_temp.dev_cmd('development.report.review',jsonb_build_object('id',current_setting('test.report'),'decision','approved','reason','Checked all report evidence'))$$,'Reviewer approves report');
select lives_ok($$select pg_temp.dev_cmd('development.report.publish',jsonb_build_object('id',current_setting('test.report')))$$,'Reviewer publishes report');
select lives_ok($$select pg_temp.dev_cmd('development.certificate.revoke',jsonb_build_object('id',current_setting('test.certificate'),'reason','Issued with incorrect award title'))$$,'Authorized reviewer revokes certificate');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_reports where id=current_setting('test.report')::uuid),1,'Parent sees reviewed published report');
select is((select count(*)::int from public.development_certificates where id=current_setting('test.certificate')::uuid),0,'Revoked certificate cannot be downloaded');
select is((select count(*)::int from public.development_certificate_revocations where certificate_id=current_setting('test.certificate')::uuid),1,'Own family sees revocation status');
select is((select count(*)::int from public.development_reviews),0,'Family cannot see internal review reasons');
select throws_ok($$update public.development_assessments set summary='Forged' where id=current_setting('test.assessment')::uuid$$,'42501',null,'Authenticated direct mutations denied');
reset role;
delete from public.branch_permissions where user_id='d1000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_assessments where id=current_setting('test.assessment')::uuid),0,'Current branch permission revocation removes coach evidence access');
select throws_ok($$select pg_temp.dev_cmd('development.plan.save','{"session_id":"d2000000-0000-4000-8000-000000000007","objectives":"Old assignment","activities":"No permission"}')$$,'42501',null,'Revoked coach cannot mutate an old assignment');
reset role;
select throws_ok($$update public.development_assessments set next_target='Rewrite published target' where id=current_setting('test.assessment')::uuid$$,'42501',null,'Published next target remains immutable with its evidence');
select throws_ok($$update public.development_reports set summary='Rewrite published report' where id=current_setting('test.report')::uuid$$,'42501',null,'Published report versions are immutable');
select throws_ok($$update public.development_certificates set title='Rewrite certificate' where id=current_setting('test.certificate')::uuid$$,'42501',null,'Certificate issue snapshot remains immutable after revocation');
select throws_ok($$update public.development_level_history set reason='rewrite' where child_id='d3000000-0000-4000-8000-000000000002'$$,'42501',null,'Level history is immutable even to privileged accidental mutation');
select throws_ok($$update public.development_criteria set title='rewrite' where level_id='d2000000-0000-4000-8000-000000000003'$$,'42501',null,'Criteria versions cannot be overwritten');

-- Corrections retain immutable evidence, history and certificate lineage.
select set_config('test.history',(select id::text from public.development_level_history where assessment_id=current_setting('test.assessment')::uuid),true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_certificate_records where id=current_setting('test.certificate')::uuid and revoked_at is not null),1,'Family can inspect a revoked certificate snapshot without PDF access');
select throws_ok($$select pg_temp.dev_cmd('development.certificate.reissue',jsonb_build_object('id',current_setting('test.certificate'),'title','Corrected certificate','reason','Corrected approved title'))$$,'42501',null,'Parent cannot reissue a certificate');
select throws_ok($$select pg_temp.dev_cmd('development.level.reverse',jsonb_build_object('id',current_setting('test.history'),'reason','Parent attempting a level reversal'))$$,'42501',null,'Parent cannot reverse an approved sport level');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select pg_temp.dev_cmd('development.certificate.reissue',jsonb_build_object('id',current_setting('test.certificate'),'title','Corrected certificate','reason','Corrected approved title'))$$,'Authorized reviewer reissues a revoked certificate as a new immutable version');
select set_config('test.certificate.v2',(select id::text from public.development_certificates where assessment_id=current_setting('test.assessment')::uuid and version=2),true);
select is((select reissue_reason from public.development_certificates where id=current_setting('test.certificate.v2')::uuid),'Corrected approved title','New replacement preserves its own correction reason after an earlier revocation');
select is((select replaces_id from public.development_certificates where id=current_setting('test.certificate.v2')::uuid),current_setting('test.certificate')::uuid,'Replacement links to the exact original issue');
select ok((select count(distinct reference) from public.development_certificate_records where assessment_id=current_setting('test.assessment')::uuid)=2,'Replacement has a distinct certificate reference');
select throws_ok($$select pg_temp.dev_cmd('development.certificate.reissue',jsonb_build_object('id',current_setting('test.certificate'),'title','Duplicate replacement','reason','Repeated old reference'))$$,'P0409',null,'Old issue cannot branch into duplicate replacements');
select throws_ok($$select pg_temp.dev_cmd('development.certificate.issue',jsonb_build_object('assessment_id',current_setting('test.assessment'),'title','Duplicate original'))$$,'P0409',null,'Original issue path cannot bypass the replacement chain');
reset role;
update public.child_sports set level_id='d2000000-0000-4000-8000-000000000003' where child_id='d3000000-0000-4000-8000-000000000002' and sport='swimming';
set local role authenticated;
select throws_ok($$select pg_temp.dev_cmd('development.level.reverse',jsonb_build_object('id',current_setting('test.history'),'reason','Current level changed since approval'))$$,'P0409',null,'Reversal refuses to overwrite a different current sport level');
reset role;
update public.child_sports set level_id='d2000000-0000-4000-8000-000000000004' where child_id='d3000000-0000-4000-8000-000000000002' and sport='swimming';
set local role authenticated;
select lives_ok($$select pg_temp.dev_cmd('development.level.reverse',jsonb_build_object('id',current_setting('test.history'),'reason','Reviewed progression was premature'))$$,'Reviewer reverses the current effective progression');
select lives_ok($$select pg_temp.dev_cmd('development.level.reverse',jsonb_build_object('id',current_setting('test.history'),'reason','Reviewed progression was premature'))$$,'Reversal retry returns existing immutable correction');
select is((select level_id from public.child_sports where child_id='d3000000-0000-4000-8000-000000000002' and sport='swimming'),'d2000000-0000-4000-8000-000000000003'::uuid,'Reversal restores the historical previous sport level');
select is((select count(*)::int from public.development_level_reversals where history_id=current_setting('test.history')::uuid),1,'Exactly one reversal records the decision');
select is((select count(*)::int from public.development_level_history where id=current_setting('test.history')::uuid),1,'Original approval remains visible in level history');
select is((select class_id from public.enrollments where id='d3000000-0000-4000-8000-000000000003'),'d2000000-0000-4000-8000-000000000006'::uuid,'Level correction does not rewrite class enrollment history');
select is((select count(*)::int from public.enrollments where child_id='d3000000-0000-4000-8000-000000000002'),1,'Level correction creates no automatic course enrollment');
select is((select count(*)::int from public.development_certificates where id=current_setting('test.certificate.v2')::uuid),0,'Progression reversal immediately withdraws affected certificate PDF access');
select is((select status from public.development_assessments where id=current_setting('test.assessment')::uuid),'published','Original published assessment remains immutable evidence');
select lives_ok($$select pg_temp.dev_cmd('development.certificate.reissue',jsonb_build_object('id',current_setting('test.certificate.v2'),'title','Reviewed foundation achievement','reason','Reissue reflects corrected approved level'))$$,'Replacement can be reissued after the reviewed level correction');
select set_config('test.certificate.v3',(select id::text from public.development_certificates where assessment_id=current_setting('test.assessment')::uuid and version=3),true);
select is((select level_name from public.development_certificates where id=current_setting('test.certificate.v3')::uuid),'Development beginner','Reissue no longer claims a reversed progression level');
select lives_ok($$select pg_temp.dev_cmd('development.certificate.reissue',jsonb_build_object('id',current_setting('test.certificate.v3'),'title','Final corrected achievement','reason','Clarified the public achievement title'))$$,'Reissuing a live certificate atomically withdraws the replaced version');
select is((select count(*)::int from public.development_certificates where assessment_id=current_setting('test.assessment')::uuid),1,'Only the current certificate version remains downloadable');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_certificate_records where assessment_id=current_setting('test.assessment')::uuid),4,'Family sees the complete issue and correction history');
select is((select reason from public.development_level_reversals where history_id=current_setting('test.history')::uuid),'Reviewed progression was premature','Family sees the explicit public reversal reason');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_certificate_records where assessment_id=current_setting('test.assessment')::uuid),0,'Unrelated family cannot inspect revoked certificate history');
select is((select count(*)::int from public.development_level_reversals),0,'Unrelated family cannot inspect progression correction history');
reset role;
select throws_ok($$update public.development_level_reversals set reason='Rewrite the reversal'$$,'42501',null,'Progression correction is append-only');
select ok((select reloptions @> array['security_invoker=true'] from pg_class where oid='public.development_certificate_records'::regclass),'Certificate history view uses invoker security over explicit authorization');
select ok(not has_function_privilege('anon','private.development_certificate_record_rows()','execute'),'Anonymous role cannot execute the certificate history helper');
select * from finish();
rollback;
